use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut brankas: BTreeMap<String, String> = BTreeMap::new();
    for baris in input.lines() {
        let b: Vec<&str> = baris.split_whitespace().collect();
        match b.as_slice() {
            ["simpan", situs, sandi] => {
                brankas.insert(situs.to_string(), sandi.to_string());
            }
            ["ambil", situs] => match brankas.get(*situs) {
                Some(s) => println!("{}", s),
                None => println!("tidak ada"),
            },
            _ => {}
        }
    }
}

