package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type misi struct {
	id    int
	judul string
}

func main() {
	var data []misi
	next := 1
	cari := func(id int) int {
		for i, m := range data {
			if m.id == id {
				return i
			}
		}
		return -1
	}
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		bagian := strings.SplitN(sc.Text(), " ", 3)
		method, path := bagian[0], bagian[1]
		switch {
		case method == "GET" && (path == "/misi" || strings.HasPrefix(path, "/misi?cari=")):
			kata := strings.ToLower(strings.TrimPrefix(path, "/misi?cari="))
			if path == "/misi" {
				kata = ""
			}
			var j []string
			for _, m := range data {
				if strings.Contains(strings.ToLower(m.judul), kata) {
					j = append(j, m.judul)
				}
			}
			if len(j) == 0 {
				fmt.Println("200 (kosong)")
			} else {
				fmt.Println("200 " + strings.Join(j, ","))
			}
		case method == "POST" && path == "/misi":
			data = append(data, misi{next, bagian[2]})
			fmt.Printf("201 %d\n", next)
			next++
		case strings.HasPrefix(path, "/misi/") && (method == "GET" || method == "DELETE"):
			id, err := strconv.Atoi(strings.TrimPrefix(path, "/misi/"))
			if err != nil {
				fmt.Println("400 id tidak valid")
			} else if i := cari(id); i < 0 {
				fmt.Println("404 tidak ditemukan")
			} else if method == "GET" {
				fmt.Println("200 " + data[i].judul)
			} else {
				data = append(data[:i], data[i+1:]...)
				fmt.Println("204")
			}
		case path == "/misi" || strings.HasPrefix(path, "/misi/"):
			fmt.Println("405 method tidak diizinkan")
		default:
			fmt.Println("404 rute tidak ada")
		}
	}
}

